// Global Rhythm Data Model + Culturally Accurate Presets
// Each rhythm is defined by pulse GROUPINGS (2+3, 3+2+2), not just time signatures

// ─── Types ──────────────────────────────────────────────────────────────────

export interface StepData {
  velocity: number;
  probability: number;
  microtime: number;
}

export interface TrackPreset {
  instrumentId: string;
  steps: number[];
  subdivisions: number;
}

export type TimeFeel = 'straight' | 'swing' | 'compound' | 'asymmetric' | 'polyrhythmic';
export type Complexity = 'beginner' | 'intermediate' | 'advanced';
export type RhythmType = 'groove' | 'odd-meter' | 'tala' | 'trance';

export interface TalaStructure {
  name: string;
  beats: number;
  vibhags: number[];
  sam: number;
  khali: number;
}

export interface PatternPreset {
  name: string;
  category: string;
  region: string;
  country: string;
  countryCode: string; // ISO 3166-1 alpha-2
  description: string;
  bpm: number;
  swing: number;
  timeSignature: [number, number];
  clavePattern?: string;
  tracks: TrackPreset[];
  variationTracks?: TrackPreset[];
  // Extended metadata
  timeFeel: TimeFeel;
  pulseGrouping: number[];
  tempoRange: [number, number];
  instrumentRoles?: {
    timeline?: string;
    groove?: string;
    bass?: string;
    pulse?: string;
    ornament?: string;
  };
  culturalDescription?: string;
  artists?: string[];
  complexity: Complexity;
  subdivisionType?: string;
  regional?: boolean; // inherited from broader region
  rhythmType?: RhythmType;
  konnakol?: boolean;
  talaStructure?: TalaStructure;
}

// ─── Velocity shorthands ────────────────────────────────────────────────────
